DROP TABLE IF EXISTS `payments`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `payments` (
  `payment_id` bigint NOT NULL AUTO_INCREMENT,
  `order_id` bigint DEFAULT NULL,
  `customer_id` bigint DEFAULT NULL,
  `vendor_id` bigint DEFAULT NULL,
  `parent_payment_id` bigint DEFAULT NULL,
  `payment_type` enum('PURCHASE','REFUND','PARTIAL_REFUND','CHARGEBACK','PAYOUT','TRANSFER','ADJUSTMENT','FEE','TIP') NOT NULL DEFAULT 'PURCHASE',
  `currency` varchar(3) NOT NULL DEFAULT 'MAD',
  `amount` decimal(12,2) NOT NULL,
  `original_amount` decimal(12,2) DEFAULT NULL,
  `discount_amount` decimal(12,2) DEFAULT NULL,
  `tax_amount` decimal(12,2) DEFAULT NULL,
  `tip_amount` decimal(12,2) DEFAULT NULL,
  `delivery_fee` decimal(12,2) DEFAULT NULL,
  `service_fee` decimal(12,2) DEFAULT NULL,
  `platform_fee` decimal(12,2) DEFAULT NULL,
  `platform_fee_percent` decimal(5,2) DEFAULT NULL,
  `vendor_amount` decimal(12,2) DEFAULT NULL,
  `exchange_rate` decimal(12,6) DEFAULT NULL,
  `settled_currency` varchar(3) DEFAULT NULL,
  `settled_amount` decimal(12,2) DEFAULT NULL,
  `payment_method` enum('CASH','CARD','DEBIT_CARD','CREDIT_CARD','WALLET','BANK_TRANSFER','DIRECT_DEBIT','PAYNOW','APPLE_PAY','GOOGLE_PAY','PAYPAL','COD','VOUCHER','STORE_CREDIT','CRYPTO','OTHERS') NOT NULL,
  `payment_gateway` varchar(50) DEFAULT NULL,
  `gateway_payment_id` varchar(255) DEFAULT NULL,
  `gateway_charge_id` varchar(255) DEFAULT NULL,
  `gateway_response_code` varchar(50) DEFAULT NULL,
  `gateway_response_message` varchar(500) DEFAULT NULL,
  `card_brand` varchar(30) DEFAULT NULL,
  `card_last_four` varchar(4) DEFAULT NULL,
  `card_exp_month` varchar(2) DEFAULT NULL,
  `card_exp_year` varchar(4) DEFAULT NULL,
  `card_holder_name` varchar(255) DEFAULT NULL,
  `card_fingerprint` varchar(255) DEFAULT NULL,
  `auth_status` enum('NOT_REQUIRED','PENDING','SUCCESSFUL','FAILED','ATTEMPTED','UNAVAILABLE') DEFAULT NULL,
  `auth_value` varchar(255) DEFAULT NULL,
  `auth_eci` varchar(10) DEFAULT NULL,
  `status` enum('PENDING','REQUIRES_ACTION','PROCESSING','AUTHORIZED','CAPTURED','COMPLETED','FAILED','CANCELLED','REFUNDED','PARTIALLY_REFUNDED','DISPUTED','EXPIRED') NOT NULL DEFAULT 'PENDING',
  `status_reason` varchar(500) DEFAULT NULL,
  `vendor_payout_status` enum('PENDING','SCHEDULED','PROCESSING','COMPLETED','FAILED','ON_HOLD','CANCELLED') DEFAULT NULL,
  `vendor_payout_reference` varchar(255) DEFAULT NULL,
  `vendor_payout_date` timestamp NULL DEFAULT NULL,
  `refunded_amount` decimal(12,2) DEFAULT NULL,
  `refund_reason` varchar(500) DEFAULT NULL,
  `refund_date` timestamp NULL DEFAULT NULL,
  `settlement_status` enum('PENDING','PROCESSING','SETTLED','FAILED') DEFAULT NULL,
  `settlement_reference` varchar(255) DEFAULT NULL,
  `settlement_date` date DEFAULT NULL,
  `risk_score` int DEFAULT NULL,
  `fraud_status` enum('NOT_CHECKED','APPROVED','REVIEW','REJECTED','BLOCKED') DEFAULT NULL,
  `fraud_reason` varchar(500) DEFAULT NULL,
  `payer_email` varchar(255) DEFAULT NULL,
  `payer_phone` varchar(50) DEFAULT NULL,
  `payer_name` varchar(255) DEFAULT NULL,
  `billing_address_line1` varchar(255) DEFAULT NULL,
  `billing_address_line2` varchar(255) DEFAULT NULL,
  `billing_city` varchar(100) DEFAULT NULL,
  `billing_state` varchar(100) DEFAULT NULL,
  `billing_postal_code` varchar(20) DEFAULT NULL,
  `billing_country` varchar(2) DEFAULT NULL,
  `ip_address` varchar(45) DEFAULT NULL,
  `user_agent` varchar(500) DEFAULT NULL,
  `device_fingerprint` varchar(255) DEFAULT NULL,
  `session_id` varchar(255) DEFAULT NULL,
  `idempotency_key` varchar(255) DEFAULT NULL,
  `external_reference` varchar(255) DEFAULT NULL,
  `invoice_number` varchar(100) DEFAULT NULL,
  `receipt_url` varchar(500) DEFAULT NULL,
  `description` varchar(500) DEFAULT NULL,
  `metadata` json DEFAULT NULL,
  `internal_notes` text,
  `failure_reason` text,
  `processed_by` varchar(100) DEFAULT NULL,
  `processed_at` timestamp NULL DEFAULT NULL,
  `captured_at` timestamp NULL DEFAULT NULL,
  `attempt_count` int DEFAULT '0',
  `last_attempt_at` timestamp NULL DEFAULT NULL,
  `next_retry_at` timestamp NULL DEFAULT NULL,
  `retryable` tinyint(1) DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`payment_id`),
  UNIQUE KEY `idx_payments_idempotency_key` (`idempotency_key`),
  KEY `idx_payments_order` (`order_id`),
  KEY `idx_payments_customer` (`customer_id`),
  KEY `idx_payments_vendor` (`vendor_id`),
  KEY `idx_payments_parent` (`parent_payment_id`),
  KEY `idx_payments_status` (`status`),
  KEY `idx_payments_payout_status` (`vendor_payout_status`),
  KEY `idx_payments_settlement_status` (`settlement_status`),
  KEY `idx_payments_gateway` (`payment_gateway`),
  KEY `idx_payments_gateway_payment_id` (`gateway_payment_id`),
  KEY `idx_payments_external_reference` (`external_reference`),
  KEY `idx_payments_created_at` (`created_at`),
  KEY `idx_payments_processed_at` (`processed_at`),
  KEY `idx_payments_settlement_date` (`settlement_date`),
  KEY `idx_payments_vendor_status` (`vendor_id`,`status`),
  KEY `idx_payments_customer_status` (`customer_id`,`status`),
  KEY `idx_payments_vendor_payout` (`vendor_id`,`vendor_payout_status`),
  CONSTRAINT `fk_payment_customer` FOREIGN KEY (`customer_id`) REFERENCES `customers` (`customer_id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `fk_payment_order` FOREIGN KEY (`order_id`) REFERENCES `orders` (`order_id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `fk_payment_parent` FOREIGN KEY (`parent_payment_id`) REFERENCES `payments` (`payment_id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `fk_payment_vendor` FOREIGN KEY (`vendor_id`) REFERENCES `vendor_details` (`vendor_id`) ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=35 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
