DROP TABLE IF EXISTS `product_locations`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `product_locations` (
  `product_id` bigint NOT NULL,
  `address_id` bigint NOT NULL,
  `sku` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Location-specific SKU identifier',
  `available` tinyint(1) NOT NULL DEFAULT '1' COMMENT 'Product availability at this location',
  `stock` int DEFAULT '0' COMMENT 'Inventory quantity at this location',
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`product_id`,`address_id`),
  UNIQUE KEY `unique_address_sku` (`address_id`,`sku`),
  KEY `idx_product_locations_product_id` (`product_id`),
  KEY `idx_product_locations_available` (`available`),
  CONSTRAINT `fk_product_locations_address` FOREIGN KEY (`address_id`) REFERENCES `addresses` (`address_id`) ON DELETE CASCADE,
  CONSTRAINT `fk_product_locations_product` FOREIGN KEY (`product_id`) REFERENCES `products` (`product_id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
