DROP TABLE IF EXISTS `product_media`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `product_media` (
  `media_id` bigint NOT NULL AUTO_INCREMENT,
  `product_id` bigint NOT NULL,
  `media_url` varchar(1000) NOT NULL,
  `media_type` enum('IMAGE','VIDEO') NOT NULL,
  `description` varchar(500) DEFAULT NULL,
  `storage_provider` enum('CLOUDFLARE','GCP','LOCAL','S3') NOT NULL,
  `mime_type` varchar(100) DEFAULT NULL,
  `width` int DEFAULT NULL,
  `height` int DEFAULT NULL,
  `duration_seconds` int DEFAULT NULL,
  `resolution` varchar(50) DEFAULT NULL,
  `size_kb` int DEFAULT NULL,
  `validation_status` enum('PENDING','REJECTED','VALIDATED') DEFAULT NULL,
  `validation_error` text,
  `uploaded_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`media_id`),
  KEY `idx_product_media_product_id` (`product_id`),
  KEY `idx_product_media_status` (`validation_status`),
  KEY `idx_product_media_type` (`media_type`),
  KEY `idx_media_product` (`product_id`),
  KEY `idx_media_status` (`validation_status`),
  KEY `idx_media_uploaded` (`uploaded_at`),
  CONSTRAINT `fk_media_product` FOREIGN KEY (`product_id`) REFERENCES `products` (`product_id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=139 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
