--
-- Table structure for table `products`
--

DROP TABLE IF EXISTS `products`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `products` (
  `product_id` bigint NOT NULL AUTO_INCREMENT,
  `sku` varchar(255) NOT NULL,
  `name` varchar(255) NOT NULL,
  `vendor_id` bigint NOT NULL,
  `category_details` json DEFAULT NULL,
  `product_image` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin,
  `price` decimal(10,2) NOT NULL,
  `is_available` tinyint(1) NOT NULL DEFAULT '1',
  `schedule` json DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `schedule_updated` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `description` varchar(1000) DEFAULT NULL COMMENT 'Product description',
  `use_vendor_schedule` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'If true, product uses vendor schedule; if false, uses own schedule',
  `stock_quantity` int DEFAULT '0',
  `reserved_quantity` int DEFAULT '0',
  PRIMARY KEY (`product_id`),
  UNIQUE KEY `uq_product_sku` (`sku`),
  KEY `fk_product_vendor` (`vendor_id`),
  KEY `idx_products_category_mvi` ((cast(json_extract(`category_details`,_utf8mb4'$[*].Category[*]') as char(100) array))),
  KEY `idx_products_subcategory_mvi` ((cast(json_extract(`category_details`,_utf8mb4'$[*].SubCategory[*]') as char(100) array))),
  CONSTRAINT `fk_product_vendor` FOREIGN KEY (`vendor_id`) REFERENCES `vendor_details` (`vendor_id`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `chk_category_details_json_valid` CHECK (json_valid(`category_details`)),
  CONSTRAINT `chk_category_details_paths` CHECK (((json_type(`category_details`) = _utf8mb4'ARRAY') and (json_length(`category_details`) > 0) and json_contains_path(`category_details`,_utf8mb4'one',_utf8mb4'$[*].Cuisinename',_utf8mb4'$[*].Category') and (json_type(json_extract(`category_details`,_utf8mb4'$[0].Category')) = _utf8mb4'ARRAY') and (json_length(json_extract(`category_details`,_utf8mb4'$[0].Category')) > 0) and ((not(json_contains_path(`category_details`,_utf8mb4'one',_utf8mb4'$[0].SubCategory'))) or (json_type(json_extract(`category_details`,_utf8mb4'$[0].SubCategory')) = _utf8mb4'ARRAY')))),
  CONSTRAINT `chk_product_image_json_valid` CHECK (((`product_image` is null) or json_valid(`product_image`))),
  CONSTRAINT `chk_product_images_array` CHECK (((`product_image` is null) or (json_contains_path(`product_image`,_utf8mb4'one',_utf8mb4'$.images') and (json_type(json_extract(`product_image`,_utf8mb4'$.images')) = _utf8mb4'ARRAY')))),
  CONSTRAINT `chk_schedule_has_any` CHECK (json_contains_path(`schedule`,_utf8mb4'one',_utf8mb4'$.weekly_schedules',_utf8mb4'$.dates',_utf8mb4'$.blackout')),
  CONSTRAINT `chk_schedule_json_valid` CHECK (json_valid(`schedule`))
) ENGINE=InnoDB AUTO_INCREMENT=130 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

