'),(48,49,'Uncle Lee\'s Chilli Crab','[\"Singaporean\", \"Chilli Crab\", \"Chinese\"]','https://tse3.mm.bing.net/th/id/OIP.VLJXzG_jTY5_umd7mv3BDQHaFD?pid=Api&P=0&h=180','Blk 22, Marine Parade, #04-09',NULL,'Singapore',NULL,'440022','Raymond Lee','+65 9234 5678','unclelee.seafood@gmail.com','2025-11-27 04:32:10','2026-01-13 16:07:26'),(49,50,'Wang\'s Homemade Dumplings','[\"Chinese\", \"Jiaozi\", \"Dumpling\", \"Soup\"]','https://tse1.mm.bing.net/th/id/OIP.5NCS4ikt_EQFRmjCS2v8YwHaEK?pid=Api&P=0&h=180','Blk 211, Toa Payoh Lor 8, #09-02',NULL,'Singapore',NULL,'310211','Aunty Wang','+65 9222 3344','wang.dumplings@outlook.com','2025-11-27 04:32:10','2026-01-13 16:07:26');
