--
-- Table structure for table `vendor_details`
--

DROP TABLE IF EXISTS `vendor_details`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `vendor_details` (
  `vendor_id` bigint NOT NULL AUTO_INCREMENT,
  `user_id` bigint DEFAULT NULL,
  `name` varchar(100) NOT NULL,
  `supportedCategories` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci,
  `image` varchar(300) DEFAULT NULL,
  `contact_name` varchar(100) DEFAULT NULL,
  `phone_number` varchar(20) DEFAULT NULL,
  `email` varchar(100) DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `description` varchar(1000) DEFAULT NULL COMMENT 'Vendor description',
  `schedule` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin,
  `schedule_updated` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`vendor_id`),
  KEY `idx_vendor_user` (`user_id`),
  KEY `idx_vendor_supported_categories_mvi` ((cast(`supportedCategories` as char(100) array))),
  CONSTRAINT `fk_vendor_user` FOREIGN KEY (`user_id`) REFERENCES `users` (`user_id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `chk_supported_is_array` CHECK ((json_type(`supportedCategories`) = _utf8mb4'ARRAY')),
  CONSTRAINT `chk_supported_json_valid` CHECK (json_valid(`supportedCategories`)),
  CONSTRAINT `chk_vendor_schedule_has_any` CHECK (((`schedule` is null) or json_contains_path(`schedule`,_utf8mb4'one',_utf8mb4'$.weekly_schedules',_utf8mb4'$.dates',_utf8mb4'$.blackout'))),
  CONSTRAINT `chk_vendor_schedule_json_valid` CHECK (json_valid(`schedule`))
) ENGINE=InnoDB AUTO_INCREMENT=55 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `vendor_details`
--

LOCK TABLES `vendor_details` WRITE;
/*!40000 ALTER TABLE `vendor_details` DISABLE KEYS */;
INSERT INTO `vendor_details` VALUES (2,1,'Aegean Grill','[\"Greek\"]','https://static.spotapps.co/website_images/ab_websites/499963_website_v1/video_poster.jpg','Elena Petrova','+65 6112 9900','hello@aegean.test','2025-11-16 16:39:03','Elena brings the sun-soaked flavors of the Mediterranean straight to your doorstep. Specializing in authentic Greek Gyros wrapped in fluffy pita with homemade tzatziki, every bite is a tribute to her family\'s recipes from Port Helen.','{\"weekly_schedules\": [{\"tz\": \"Asia/Singapore\", \"end\": \"01:31\", \"start\": \"05:25\", \"day_of_week\": [\"Fri\"]}]}','2026-01-13 16:15:43'),(3,2,'Ah Ma\'s Nourishing Soups','[\"Chinese\"]','https://images.squarespace-cdn.com/content/v1/659847a8a9bad85f105a6b16/423b72a5-235c-48ef-9fdc-6016894ea8d9/ahma_soup_lifestyle_6_23_d.JPG?format=1500w','Evelyn Tan','+65 8111 2233','ahmasoups@gmail.com','2025-11-16 16:41:33','Warm your soul with Evelyn\'s traditional Cantonese slow-boiled soups. Simmered for over 8 hours using premium herbs and fresh ingredients, our herbal soups are crafted to restore balance, boost immunity, and taste exactly like home.',NULL,'2026-01-13 16:41:45'),(4,3,'Anjappar Chettinad','[\"Indian\", \"Mexican\"]','https://x4.sdimgs.com/sd_static/u/202212/639c41a608499.jpg','Mr. K. Palani','+65 6296 5545','contact@anjappar.test','2025-11-16 16:43:44','Experience the legendary taste of Anjappar, the world\'s most renowned Chettinad restaurant brand. We serve authentic, fiery South Indian delicacies prepared with fresh spices flown in directly from Karaikudi. A tradition of excellence since 1964.',NULL,'2026-01-13 16:41:45'),(5,4,'Aroi Mak Thai Kitchen','[\"Thai\"]','https://tickikids.ams3.cdn.digitaloceanspaces.com/z4.cache/gallery/activities/13919/image_5f45151063ab36.64530573.jpg','Ploy','+65 9555 6677','aroi.mak@gmail.com','2025-11-16 16:46:57','Sawadee ka! Ploy brings the bustling streets of Bangkok to her home kitchen. \'Aroi Mak\' means \'very delicious,\' and our signature Green Curry and Tom Yum soups live up to the name. Authentic, spicy, and made with zero MSG.',NULL,'2026-01-13 16:41:45'),(6,5,'The Samosa Hub','[\"Indian\"]','https://tse1.mm.bing.net/th/id/OIP.3eDAiPDSIF3O4Ba4DJO2kgHaHU?cb=ucfimg2ucfimg=1&rs=1&pid=ImgDetMain&o=7&rm=3','Ravi Kumar','+65 9101 2020','samosa.hub.sg@gmail.com','2025-11-16 16:52:20','The ultimate tea-time snack! Ravi Kumar\'s golden, crispy samosas are generously stuffed with spiced potatoes, peas, or minced meat. Freshly fried and served with our signature tamarind and mint chutneys.',NULL,'2026-01-13 16:41:45'),(7,6,'The Green Bowl','[\"Health Food\"]','https://image.shutterstock.com/image-photo/hands-holding-healthy-fresh-green-260nw-1502021276.jpg','Sarah Lim','+65 9777 8899','green.bowl.sg@gmail.com','2025-11-16 16:54:48','Eat clean, live green. Sarah curates nutrient-dense salad bowls featuring locally sourced hydroponic greens, roasted proteins, and homemade dressings. Fully customizable and perfect for your daily dose of vitamins.',NULL,'2026-01-13 16:41:45'),(8,7,'Mrs. Singh\'s Punjabi Kitchen','[\"Indian\"]','https://images.squarespace-cdn.com/content/v1/60ecba6b81342d312c36d496/c1e6bdec-5296-46d7-b182-93ebfe53b95b/singhskitchenlogo.png','Jaspreet Kaur','+65 9876 5432','singh.kitchen@gmail.com','2025-11-16 16:57:38','Craving authentic North Indian food? We are a Home Based Business located in Clementi, Singapore, serving up delicious Punjabi specialties.',NULL,'2026-01-13 16:41:45'),(9,8,'Mummy\'s Briyani (Home Cook)','[\"Indian\", \"Side\"]','https://wallpaperaccess.com/full/8734370.jpg','Fatima Shaffi','+65 9123 4567','mummysbriyani@gmail.com','2025-11-16 17:01:32','Famous for our weekend specials! Fatima Shaffi prepares authentic Hyderabadi Dum Briyani, layered with fragrant basmati rice and tender marinated meat. Cooked slowly in a sealed pot (dum) to lock in the aroma and spices.',NULL,'2026-01-13 16:41:45'),(10,9,'Keto Kitchen SG','[\"Health Food\"]','https://ugc.production.linktr.ee/XAbWEbQtG7skC6wn7JAM_t1hGwT3MsXE8OXYU?io=true&size=avatar-v3_0','Alex','+6S 8888 9900','keto.kitchen@gmail.com','2025-11-16 17:06:03','Guilt-free indulgence starts here. Alex crafts delicious, low-carb, and sugar-free meals designed to keep you in ketosis without sacrificing flavor. From cauliflower-crust pizzas to almond flour brownies, we make healthy eating easy.',NULL,'2026-01-13 16:41:45'),(11,10,'Li\'s Kitchen (Hakka Food)','[\"Chinese\", \"Noodle\"]','https://tse1.mm.bing.net/th/id/OIP.f1rVUQIKPFdgZR8gPQnh1wHaHa?cb=ucfimg2ucfimg=1&rs=1&pid=ImgDetMain&o=7&rm=3','Ah Li','+65 9776 6554','li.hakka@gmail.com','2025-11-16 17:09:01','Rediscover the lost art of traditional Hakka cuisine. Ah Li specializes in heritage dishes like Yam Abacus Seeds and Lei Cha, painstakingly prepared by hand to preserve the authentic textures and savory flavors of the old days.',NULL,'2026-01-13 16:41:45'),(12,11,'Simply Viet (Home)','[\"Thai\"]','https://th.bing.com/th/id/OIP.feR6FPhlAEy369OXt79dwgHaHa?w=181&h=181&c=7&r=0&o=7&cb=ucfimg2&dpr=2.2&pid=1.7&rm=3&ucfimg=1','Ms. Thuy','+65 8444 5566','simply.viet.sg@gmail.com','2025-11-16 23:19:20','Ms. Thuy brings the authentic crunch of Saigon to Singapore. Our Banh Mi is made with fresh, airy baguettes, savory homemade pate, and pickled vegetables. A perfect balance of savory, sour, and spicy in every bite.',NULL,'2026-01-13 16:41:45'),(13,12,'Priya\'s Home Kitchen (Veg)','[\"Indian\", \"Noodle\"]','https://www.bing.com/th/id/OIP.lnznpPWRiz5_sUE2EheosQHaEK?w=274&h=211&c=8&rs=1&qlt=90&o=6&cb=ucfimg1&dpr=2.2&pid=3.1&rm=2&ucfimg=1','Priya Suresh','+65 8765 4321','priya.kitchen.sg@gmail.com','2025-11-16 23:21:33','Looking for pure vegetarian comfort food? We are a Home Based Business in Punggol serving traditional South Indian favorites. Fresh, homemade, and delicious!',NULL,'2026-01-13 16:41:45'),(14,13,'ArtisanSlice','[\"Pizza\", \"Sourdough Pizza\", \"Pizzeria\", \"French\"]',NULL,'TonyBianco','6569991234','pizza@artisan.test','2025-11-27 04:32:10','Tony Biancoâ€™s hand-stretched sourdough pizzas. Fermented for 48 hours for a light','{\"weekly_schedules\": [{\"tz\": \"Asia/Singapore\", \"end\": \"18:00\", \"start\": \"09:00\", \"day_of_week\": [\"Mon\", \"Tue\", \"Wed\", \"Thu\", \"Fri\"]}]}','2026-01-13 16:41:45'),(15,14,'Bangkok Spice','[\"Thai\", \"Home Cook\", \"Stir-Fry\", \"Curry\", \"Soup\"]',NULL,'Anya Sharma','+65 6443 2211','support@bangkokspice.test','2025-11-27 04:32:10','Anya Sharmaâ€™s fusion Thai kitchen. Spicy stir-fries and aromatic soups inspired by the street food of Bangkok.','{\"weekly_schedules\": [{\"tz\": \"Asia/Singapore\", \"end\": \"18:00\", \"start\": \"09:00\", \"day_of_week\": [\"Mon\", \"Tue\", \"Wed\", \"Thu\", \"Fri\"]}]}','2026-01-13 16:41:45'),(16,15,'BeirutBites','[\"MiddleEastern\", \"Shawarma\", \"Home Cook\", \"Appetizer/Starter\", \"Side\"]',NULL,'FatimaAl-Amin','6563078901','info@beirutbites.test','2025-11-27 04:32:10','Fatima Al-Amin offers a taste of Lebanon. Authentic Shawarma wraps and mezze platters rich in olive oil and garlic.','{\"weekly_schedules\": [{\"tz\": \"Asia/Singapore\", \"end\": \"18:00\", \"start\": \"09:00\", \"day_of_week\": [\"Mon\", \"Tue\", \"Wed\", \"Thu\", \"Fri\"]}]}','2026-01-13 16:41:45'),(17,16,'Chen\'s Confinement Food','[\"Chinese\", \"Confinement\", \"Home Based Business\"]',NULL,'Mrs. Chen','+65 8888 1234','chen.confinement@gmail.com','2025-11-27 04:32:10','Specialized nutritional meals designed for postnatal recovery. Mrs. Chen prepares balanced','{\"weekly_schedules\": [{\"tz\": \"Asia/Singapore\", \"end\": \"18:00\", \"start\": \"09:00\", \"day_of_week\": [\"Mon\", \"Tue\", \"Wed\", \"Thu\", \"Fri\"]}]}','2026-01-13 16:41:45'),(18,17,'Crystal Jade Palace','[\"Chinese\", \"Cantonese\", \"Restaurant\"]',NULL,'Manager','+65 6735 2388','palace@crystaljade.test','2025-11-27 04:32:10','An award-winning culinary institution serving exquisite Cantonese cuisine. Known for premium ingredients','{\"weekly_schedules\": [{\"tz\": \"Asia/Singapore\", \"end\": \"18:00\", \"start\": \"09:00\", \"day_of_week\": [\"Mon\", \"Tue\", \"Wed\", \"Thu\", \"Fri\"]}]}','2026-01-13 16:41:45'),(19,18,'Din Tai Fung','[\"Chinese\", \"Taiwanese\", \"Restaurant\"]',NULL,'Guest Relations','+65 6836 8336','service@dintaifung.test','2025-11-27 04:32:10','World-renowned for their precision-made Xiao Long Bao (soup dumplings). A Taiwanese staple offering consistently delicious noodles.','{\"weekly_schedules\": [{\"tz\": \"Asia/Singapore\", \"end\": \"18:00\", \"start\": \"09:00\", \"day_of_week\": [\"Mon\", \"Tue\", \"Wed\", \"Thu\", \"Fri\"]}]}','2026-01-13 16:41:45'),(20,19,'Fudgy Bakes by H','[\"Dessert\", \"Brownies\", \"Home Based Business\"]',NULL,'Halimah','+65 8222 3344','fudgy.bakes@gmail.com','2025-11-27 04:32:10','Halimahâ€™s decadent chocolate brownies are legendary. Gooey centers','{\"weekly_schedules\": [{\"tz\": \"Asia/Singapore\", \"end\": \"18:00\", \"start\": \"09:00\", \"day_of_week\": [\"Mon\", \"Tue\", \"Wed\", \"Thu\", \"Fri\"]}]}','2026-01-13 16:41:45'),(21,20,'Gerrys Grill SG','[\"Filipino\", \"Inihaw\", \"Restaurant\"]',NULL,'Annabelle Cruz','+65 6734 7311','gerrys@grill.test','2025-11-27 04:32:10','The go-to place for Filipino favorites. Famous for Inihaw (grilled) dishes and sizzling plates perfect for sharing with beer.','{\"weekly_schedules\": [{\"tz\": \"Asia/Singapore\", \"end\": \"18:00\", \"start\": \"09:00\", \"day_of_week\": [\"Mon\", \"Tue\", \"Wed\", \"Thu\", \"Fri\"]}]}','2026-01-13 16:41:45'),(22,21,'GoaGrill','[\"Indian\", \"Goan\", \"Restaurant\"]',NULL,'David Braganza','+65 6440 0230','bookings@goagrill.test','2025-11-27 04:32:10','Experience the tropical flavors of Goa with David Braganzaâ€™s seafood-heavy menu','{\"weekly_schedules\": [{\"tz\": \"Asia/Singapore\", \"end\": \"18:00\", \"start\": \"09:00\", \"day_of_week\": [\"Mon\", \"Tue\", \"Wed\", \"Thu\", \"Fri\"]}]}','2026-01-13 16:41:45'),(23,22,'Hunan Kitchen','[\"Chinese\", \"Hunan\", \"Restaurant\"]',NULL,'Chef Liu','+65 6338 5